function getFullNoticeTextForCourse(courseName,domainType=null){
if(!courseName)return'';
const stdCourse=normalizeNoticeCourseName(courseName);
const normTarget=stdCourse.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi,'').toLowerCase();
const matchingRules=activeNoticeRules.filter(r=>{
if(!r.course)return false;
if(!isCourseMatch(stdCourse,r.course))return false;
const isMeal=r.type==='\x6d\x65\x61\x6c'||(r.isMeal&&(r.price===null||r.price===undefined));
if(domainType==='\x6d\x65\x61\x6c'&&!isMeal)return false;
if(domainType==='\x70\x72\x69\x63\x65'&&isMeal)return false;
return true;
});
matchingRules.sort((a,b)=>(b.receivedTimestamp||0)-(a.receivedTimestamp||0));
const distinctTexts=[...new Set(matchingRules.map(r=>(r.fullNoticeText||r.rawNoticeText||'').trim()).filter(Boolean))];
if(distinctTexts.length===1){
return distinctTexts[0];
}else if(distinctTexts.length>1){
return distinctTexts.join('\n\n--- [\ucd94\uac00 \ubcd1\ud569\ub41c \uacf5\uc9c0] ---\n\n');
}
if(typeof lastCollectedKakaoNotices!=='\x75\x6e\x64\x65\x66\x69\x6e\x65\x64'&&Array.isArray(lastCollectedKakaoNotices)&&lastCollectedKakaoNotices.length>0){
const matchedItem=lastCollectedKakaoNotices.find(item=>{
if(!item.text)return false;
const normText=item.text.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi,'').toLowerCase();
return normText.includes(normTarget)||(item.course&&isCourseMatch(stdCourse,item.course));
});
if(matchedItem&&matchedItem.text){
return matchedItem.text;
}
}
if(matchingRules.length>0){
const lines=[];
const r0=matchingRules[0];
const domainLabel=domainType==='\x6d\x65\x61\x6c'?' [\uc2dd\uc0ac\ud3ec\ud568]':(domainType==='\x70\x72\x69\x63\x65'?' [\uac00\uaca9]':'');
lines.push(`\u25a0 ${stdCourse}${domainLabel}`);
if(r0.receivedAt||r0.receivedTimestamp)lines.push(`[\uacf5\uc9c0 \uc218\uc2e0 \uc77c\uc2dc: ${formatNoticeReceivedTime(r0.receivedAt,r0.receivedTimestamp)}]`);
if(r0.dateRange)lines.push(`\uae30\uac04: ${r0.dateRange.text}`);
else if(r0.date)lines.push(`\ub0a0\uc9dc: ${r0.date}`);
lines.push('');
matchingRules.forEach(r=>{
if(r.type==='\x74\x61\x72\x67\x65\x74'){
const startH=Math.floor(r.startMins/60);
const startM=r.startMins%60;
const endH=Math.floor(r.endMins/60);
const endM=r.endMins%60;
const timeDesc=(r.startMins===r.endMins)
?`${String(startH).padStart(2,'\x30')}:${String(startM).padStart(2,'\x30')}`
:(r.endMins-r.startMins===59&&startM===0)
?`${startH}\uc2dc\ub300`
:`${String(startH).padStart(2,'\x30')}:${String(startM).padStart(2,'\x30')} ~ ${String(endH).padStart(2,'\x30')}:${String(endM).padStart(2,'\x30')}`;
const mealSfx=r.isMeal?' [\ud83c\udf5a\uc2dd\uc0ac\ud3ec\ud568]':'';
lines.push(`${r.date?`${r.date} `:''}${timeDesc} : ${r.price}\ub9cc${r.slashBackPrice?` / ${r.slashBackPrice}\ub9cc`:''}${mealSfx}`);
}else if(r.type==='\x64\x69\x73\x63\x6f\x75\x6e\x74'){
const mealSfx=r.isMeal?' [\ud83c\udf5a\uc2dd\uc0ac\ud3ec\ud568]':'';
lines.push(`\ucd94\uac00 \ud560\uc778: -${r.discount}\ub9cc (${r.parts?r.parts.desc:'\uc804\ubd80'})${mealSfx}`);
}else if(r.type==='\x6d\x65\x61\x6c'||r.isMeal){
lines.push(`${r.date?`${r.date} `:''}${r.timeText||'\uc804\ud0c0\uc784'} : \ud83c\udf5a\uc2dd\uc0ac\ud3ec\ud568${r.parts?` (${r.parts.desc})`:''}`);
}
});
return lines.join('\n');
}
return`[${stdCourse}] \ub4f1\ub85d\ub41c \uacf5\uc9c0 \uc6d0\ubb38\uc744 \ucc3e\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.`;
}
